import{_ as t,o as s,c as e,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"Embodied Tree of Thoughts: Deliberate Manipulation Planning with Embodied World Model","description":"","frontmatter":{"title":"Embodied Tree of Thoughts: Deliberate Manipulation Planning with Embodied World Model","arxiv":"2512.08188","date":"2025-12-09","authors":"Wenjiang Xu, Cindy Wang, Rui Fang, Mingkang Zhang, Lusong Li, Jing Xu, Jiayuan Gu, Zecui Zeng, Rui Chen","categories":"cs.RO, cs.AI, cs.CV","topics":"具身世界模型, 操作规划树搜索, 物理感知视频生成","outline":[2,2]},"headers":[],"relativePath":"papers/2512.08188.md","filePath":"papers/2512.08188.md","lastUpdated":null}'),o={name:"papers/2512.08188.md"};function r(i,a,l,p,d,h){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="embodied-tree-of-thoughts-deliberate-manipulation-planning-with-embodied-world-model" tabindex="-1">Embodied Tree of Thoughts: Deliberate Manipulation Planning with Embodied World Model <a class="header-anchor" href="#embodied-tree-of-thoughts-deliberate-manipulation-planning-with-embodied-world-model" aria-label="Permalink to &quot;Embodied Tree of Thoughts: Deliberate Manipulation Planning with Embodied World Model&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.08188" target="_blank" rel="noreferrer">2512.08188</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-09</td></tr><tr><td><strong>作者</strong></td><td>Wenjiang Xu, Cindy Wang, Rui Fang, Mingkang Zhang, Lusong Li, Jing Xu, Jiayuan Gu, Zecui Zeng, Rui Chen</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把真实场景重建成物理仿真里的可交互数字孪生当世界模型，用它对 VLM 生成的多分支操作计划做树搜索，并在仿真失败时反思式地扩展修正分支。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人操作规划需要预测&quot;执行这个动作会发生什么&quot;。近来的主流做法是拿视频生成模型当世界模型：给当前帧和动作指令，让它生成未来画面，再让 VLM 看着画面判断可行性。这条路在短程上能用，长程上会崩——像素空间的预测没有显式物理约束，接触密集的交互会产生累积性的幻觉。</p><p>论文给了一个极其具体的失败案例：任务是&quot;把笔插进 2 号笔筒&quot;，但笔筒里已经有一个苹果。物理仿真正确预测出笔接触苹果后滑落；视频生成模型则画出了笔顺利插进去的画面。VLM 基于这个错误预测认可了计划，真机执行必然失败。这不是模型不够大的问题——生成模型的训练目标是像素似然，没有任何机制保证刚体不能互相穿透。</p><p>论文的立场是：既然 3D AIGC 和高保真仿真平台已经成熟，就该让世界模型回到物理引擎里。仿真器不仅强制刚体动力学与碰撞约束，还直接暴露质量、摩擦、关节限位这些长程规划需要的隐变量。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>视频/3D 生成类世界模型</strong>（VLMPC、Reflective Planning、3DFlowAction、ManiGaussian）表达力强，但缺显式物理约束，长程因果一致性差，零样本逻辑约束（比如检测被遮挡的几何干涉）基本做不到。</p><p><strong>Real2Sim 类</strong>里最接近的是 PWTF——它用可交互数字孪生做 model predictive control，采样低层动作、渲染预测结果、用 VLM 评估。论文点出的局限很精确：<strong>PWTF 只把世界模型用在低层控制上，高层规划仍是单一固定的任务分解</strong>。没有能力用世界模型的反馈去批判或修改高层计划，于是任何初始分解错误都不可逆地导致失败。这不是&quot;前人没考虑高层规划&quot;，而是把世界模型接进高层需要一个搜索结构，而这个结构此前没有被建起来。</p><p><strong>VLM 规划类</strong>（Look Before You Leap、Inner Monologue、ReKep、CoPa、OmniManip）把语言计划落到可执行几何上，但依赖静态几何观测，没有物理引擎预测动态演化。<strong>树搜索类</strong>（Tree-Planner、Prime the Search、STEP Planner）改进了搜索效率，但节点可行性判定靠语义或几何启发式，或者靠 LLM 的语义一致性——在碰撞、可达性、支撑条件这些无法用语言显式编码的隐性物理约束面前，这些判据会系统性地幻觉。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已有的三条线索：Tree of Thoughts 已经证明，让 LLM 展开多条推理路径再搜索，比单链推理强得多；Reflect 之类工作证明失败后的反思能提升鲁棒性；PWTF 证明数字孪生可以作为可靠的前向预测器。</p><p>把它们组合起来的推理是：树搜索的瓶颈在<strong>节点评估函数</strong>——LLM 自己评估自己的计划，等于让幻觉自我认证。如果换成物理仿真器来评估节点，评估就有了外部的、不可被语言说服的依据。这解决了树搜索的可信度问题。</p><p>但仅有 Priori Branching（提前枚举候选）还不够，因为很多失败是执行时才暴露的——比如开抽屉会把网球扫下桌。这时仿真器不只是通过/否决的裁判，它还产出了<strong>可视化的失败现场</strong>，可以喂回 VLM 让它诊断原因并提出修正动作（先把球挪走）。这类修正动作往往根本不在原始指令里，纯语义规划推不出来。于是两种分支机制天然互补：一个提供广度，一个提供深度和自我修正。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>树搜索的价值取决于节点评估的可信度。让 VLM 评估自己想出的计划，等于用幻觉验证幻觉。把评估交给物理引擎——它无法被说服相信笔能穿过苹果——树搜索才真正起作用。更关键的是，仿真失败不只给出&quot;不行&quot;，还给出可看的失败画面，VLM 能据此诊断出&quot;因为苹果挡着&quot;，并生成原指令里根本没有的修正步骤。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Task 5 &quot;把笔重新定向并放进笔筒&quot;为例（白色笔筒上放着一个苹果）：</p><ol><li><strong>动作原语集</strong>：五个离散语义原语——<code>[PICK UP, obj]</code>、<code>[PUT ON, surface]</code>、<code>[PUT INTO, container]</code>、<code>[OPEN, obj]</code>、<code>[CLOSE, obj]</code>。PICK UP 用 AnyGrasp 从 RGB-D 估计抓取位姿与夹爪宽度；对有多种抓法的物体额外提供 <code>[PICK UP, obj](POSE)</code> 做区分。</li><li><strong>数字孪生构建</strong>：单张 RGB-D 起步。SAM-3 抽物体掩码 → SAM-3D-Objects 生成带纹理网格 → DexSim2Real2 的尺寸估计模块恢复真实尺度 → FoundationPose 估计位姿 → 导入 OmniGibson。铰接物体需要额外一张不同视角、不同关节状态的 RGB-D，由 DexSim2Real2 恢复关节结构。非凸网格（如笔筒）需先用 COACD 做凸分解，否则 OmniGibson 默认的凸包会把笔筒口封死。</li><li><strong>Priori Branching</strong>：VLM 读 RGB 与指令，抽物体信息、推关系谓词（&quot;笔在抽屉上&quot;）与铰接状态（&quot;抽屉是关的&quot;），然后生成多条完整候选分支。分两类：实例级分支（放进 1 号还是 2 号笔筒）与操作参数级分支（横抓还是竖抓）。共享前缀的分支合并，得到紧凑的树。</li><li><strong>树搜索与 Reflective Branching</strong>：BFS 逐层遍历。每个节点在仿真器里执行 → 得到 rollout 图像集 → VLM 判定。判定不只看任务目标是否达成，还看有没有不可恢复的副作用（网球滚下桌、笔滑出可达范围都算不安全）。失败则进入反思：VLM 诊断原因并提修正策略，主要两类——碰撞扰动（先把受影响物体挪到安全位置）与顺序冲突（重排动作，比如先把笔筒放到抽屉上再放苹果）。</li><li><strong>闭环执行</strong>：真机每执行一个动作，VLM 用真实相机观测做与仿真一致的评估；失败则把当前场景重建为新的初始状态，作为根节点重新规划。</li></ol><p>在这个例子里，仿真正确预测出笔碰到苹果后反弹，反思分支生成&quot;先移走苹果&quot;，最终计划才可行。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。方法的核心是算法层面的树构造与搜索（论文 Algorithm 1）：从 <code>PrioriBranching(I, t)</code> 得到初始树 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">T</span></span></span></span>，把根节点的子节点入队 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8805em;vertical-align:-0.1944em;"></span><span class="mord mathbf">Q</span></span></span></span>；每次出队一个节点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">N</span></span></span></span>，在仿真器执行其动作得到图像集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0738em;">I</span></span></span></span>，由 <code>VLMJudge</code> 给出结果 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">R</span></span></span></span>；成功且是叶节点则返回路径，成功但非叶则子节点入队；失败则触发 Reflective Branching 生成修正分支 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">B</span></span></span></span>，与现有树合并后把第一个非重叠节点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">n</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">new</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 入队。可行性判据完全由仿真 rollout 与 VLM 视觉判断给出，没有解析形式的代价函数。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>硬件是 xArm6 六自由度机械臂加平行夹爪与 Azure Kinect DK，VLM 统一用 GPT-4o，每任务重复 10 次独立试验。为公平起见，所有方法共用同一套关键点标注与动作原语 API。</p><p><strong>任务设计</strong>围绕四种能力：物体可操作性感知、三维空间关系理解、物理动力学预测、扰动鲁棒性与自动恢复。短程任务 1–4 加一个扰动任务，长程任务 5–7。每个任务都埋了一个非平凡的物理陷阱：Task 1 直接开微波炉门会把网球扫下桌；Task 3 笔筒略宽于夹爪且摩擦低，横向侧抓必滑；Task 4 抽屉里的玩具高于内腔，直接推会卡住；Task 7 苹果高度超过抽屉、网球初始位置正挡在抽屉前方。</p><p><strong>主结果</strong>：EToT 平均成功率 88.8%（ReKep 16.3%、ReKep w/ CoT 38.8%、Reflect* 66.3%）。分解看更有信息量——ReKep w/ CoT 在 Task 1、4 上靠链式推理拿到 8/10，说明&quot;开门会碰到球&quot;这类风险 CoT 能推出来；但 Task 3 拿 0/10，因为&quot;低摩擦加接近极限夹爪宽度导致滑脱&quot;无法从静态图像语义推出。Reflect* 在 Task 3 拿 8/10（失败一次后换策略即可）和扰动任务 10/10，但在 Task 6 只有 5/10——苹果一旦掉进笔筒就不可逆，事后反思救不回来。这组对比精确划出了&quot;事后反思&quot;与&quot;事前仿真&quot;的分界线：<strong>可逆失败靠反思，不可逆失败必须提前预测</strong>。长程任务上三个 baseline 全都不超过 50%，EToT 是 8/10、9/10、7/10。</p><p><strong>ablation</strong>：去掉 Priori Branching 降到 61.3%（多路径任务 2、5、7 上因单分支承诺而无法恢复）；去掉 Reflective Branching 暴跌到 35.0%（Task 1、4 和全部长程任务归零）；去掉真机重规划为 75.0%，短程基本不受影响但扰动任务 0/10；把物理仿真器换成视频生成模型（VGM）降到 21.3%——比不用世界模型还惨，因为错误预测比没有预测更有害。</p><p><strong>失败分析</strong>：执行误差 44.44%（未建模的接触动力学与控制精度）、深度估计误差 44.44%（深度噪声让抓取位姿偏移）、世界模型规划误差仅 11.11%。这个分布很值得注意——EToT 剩余的失败大部分不在规划层，而在感知与执行层。<strong>并行加速</strong>：把待评估的子节点批量化、各自从父节点终态初始化并行执行，Task 7 的推理时间降低约 50%。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频生成模型当世界模型在接触密集的长程操作上会给出物理错误的预测，误导规划。EToT 把真实场景重建成 OmniGibson 里的可交互数字孪生，用物理引擎充当节点评估器。规划被表述为树搜索：Priori Branching 提供实例级与抓取参数级的多候选广度，Reflective Branching 在仿真失败时诊断原因并生成原指令中不存在的修正动作。七个真机任务上平均成功率 88.8%，长程任务上所有 baseline 都低于 50%。把仿真器换成视频生成模型后降到 21.3%，反过来证明了物理一致预测的必要性。</p><p><strong>3 句话版</strong>：树搜索有没有用取决于节点评估可不可信，让 LLM 评估自己的计划等于自我认证幻觉。换成物理仿真器评估，既得到不可被说服的可行性判据，又得到可诊断的失败现场。事后反思只能救可逆失败，事前仿真才能避开不可逆失败。</p><p><strong>1 句话版</strong>：把真实桌面搬进物理引擎当世界模型，让 VLM 的操作计划先在里面走一遍树搜索再上真机。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是 <strong>Real2Sim 重建的保真度足以让仿真预测迁移到真机</strong>。整个框架的可信度建立在&quot;仿真里失败的，真机也会失败；仿真里成功的，真机也能成功&quot;之上。而重建链条很长：SAM-3 分割 → SAM-3D-Objects 生成网格 → DexSim2Real2 估尺度 → FoundationPose 估位姿 → COACD 凸分解 → 导入 OmniGibson，每一环都会引入误差，而且论文自己说明多处需要&quot;少量人工修正&quot;。</p><p>更关键的是<strong>物理参数</strong>：Task 3 的核心机制是&quot;笔筒表面摩擦低导致侧抓滑脱&quot;，这要求仿真器里的摩擦系数与真实材料接近。论文没有说明摩擦、质量这些参数从哪来——从单张 RGB-D 无法估计摩擦系数，只能靠默认值或人工设定。可以推断，这些参数在当前实验里很可能是手工调过的，那么&quot;仿真预测出滑脱&quot;就部分是被设计出来的结果，而非从重建自动涌现。</p><p>论文提供的支持证据是端到端的真机成功率与失败分析（WM 规划误差仅 11.11%），这确实说明在测试的七个任务上仿真足够准。但缺的证据是：sim-to-real 预测一致性的直接量化（例如仿真判定成功的动作在真机上的实际成功率），以及物理参数扰动下的敏感性分析。缺了这两项，就无法判断 88.8% 里有多少来自方法、多少来自针对这批物体的仿真调参。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要真机：</p><ul><li>场景：在 OmniGibson 或任一支持刚体接触的仿真器里手工搭三个场景，对应论文的三类物理陷阱——容器内已有障碍物（笔+苹果+笔筒）、抽屉内物体超高、低摩擦宽物体的侧抓。</li><li>实现：只做 Priori Branching 加仿真评估，跳过 Real2Sim 重建（直接用仿真器自带资产，从而隔离重建误差）和真机执行。VLM 用任一多模态 API。</li><li>对照：同一个 VLM 在纯图像上做单链 CoT 规划，不给仿真反馈。</li><li>测量：两者在这三个场景上给出正确计划的比例（各 10 次）。</li><li>判定：若仿真评估版显著高于纯 CoT，说明增益确实来自物理评估而非 VLM 本身能力；若 CoT 在给定完美仿真资产渲染图的情况下也能推对，则说明论文的增益部分来自&quot;重建后的渲染图更清晰&quot;这个混淆因素。</li></ul><p>这个设计的价值在于把&quot;物理引擎评估的贡献&quot;与&quot;Real2Sim 重建质量的贡献&quot;彻底分开——论文的 ablation 没有做这个切分。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是构造一类<strong>仿真自信但真机会失败</strong>的任务：涉及可变形物体、流体或精细接触的场景。比如&quot;把湿抹布拧干后挂到架子上&quot;、&quot;把面团摊开&quot;、&quot;把纸张对折&quot;。刚体仿真器在这些任务上不会报错——它会给出一个看起来合理的刚体近似 rollout，VLM 看着这个 rollout 会判定成功，然后真机彻底失败。</p><p>这构成了对论文核心 claim 的可预测失败条件：EToT 的优势来自&quot;仿真器无法被说服相信物理上不可能的事&quot;，但这只在仿真器的物理模型覆盖了任务所需的物理时成立。一旦任务的关键物理（形变、粘附、摩擦各向异性）不在刚体模型里，仿真器就从&quot;不可被说服的裁判&quot;退化成&quot;另一个会自信地给出错误预测的模型&quot;——与它批评的 VGM 处于同一类失败，只是失败模式不同。论文的七个任务全部是刚体 pick-and-place，恰好落在仿真器的舒适区内。</p><p>另一个替代解释：EToT 的性能优势有一部分可能来自<strong>搜索预算不对等</strong>。EToT 会展开并评估多个分支，baseline 只走一条路径。一个更公平的对照是给 ReKep w/ CoT 同样次数的采样与自我一致性投票（self-consistency），看纯语言侧的多次采样能挽回多少差距。论文没有做这个对照。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：数字孪生是<strong>一次性重建、静态使用</strong>的——从初始 RGB-D 建好之后，物理参数就固定了。执行过程中真机反馈只用来触发重新规划，从不用来修正仿真器本身。这意味着摩擦估错就会一直错，同一类错误会在每个任务上重复犯。</p><p><strong>新 framing</strong>：把数字孪生从&quot;预测器&quot;改造成&quot;<strong>在线辨识的信念状态</strong>&quot;。把物理参数（摩擦、质量、关节阻尼）当作待推断的隐变量，每次真机执行的结果都是一次对这些参数的观测；规划不再是在单个确定性仿真上搜索，而是在参数后验分布上做鲁棒规划——只有在参数后验的大部分样本下都成功的计划才被采纳。这同时解决了 §9 的调参依赖与 §11 的过度自信问题。</p><p><strong>可借鉴的相邻工具</strong>：sim-to-real 领域的 domain randomization 与 real-to-sim 参数辨识（如 BayesSim、DROPO），以及 POMDP 规划里的 belief-space planning——后者提供了&quot;在状态不确定下如何搜索&quot;的现成算法，且天然支持信息收集动作（主动做一个小试探来降低参数不确定性）。</p><p><strong>第一个实验</strong>：在论文的 Task 3（低摩擦笔筒侧抓）上，把摩擦系数从固定值改为一个先验分布，用 20 个采样参数并行仿真同一个动作，统计成功比例作为该节点的可行性分数。第一个要看的是：这个分布式评估能否在<strong>不手工调摩擦</strong>的前提下依然正确否决侧抓分支。如果可以，说明当前方法对物理参数调参的依赖可以被系统性消除；如果不行，就精确量化出了 Real2Sim 世界模型在参数辨识上的真实缺口有多大。</p>',50)])])}const g=t(o,[["render",r]]);export{c as __pageData,g as default};
